head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/

//----W-Craft WebSquare 변환 확인: include----//

//----W-Craft WebSquare 변환 확인: include----//

//----W-Craft WebSquare 변환 확인: include----//

//----W-Craft WebSquare 변환 확인: include----//
scwin.vScrenID = "ULDSTF92009.gfm";

//----W-Craft WebSquare 변환 확인: fn_GetPar----//

//----W-Craft WebSquare 변환 확인: fn_SetPar----//
scwin.fn_GetPar, scwin.fn_SetPar, scwin.strCdSch;
scwin.fr_MktId = $c.lc.fn_getMktId(); // 시장구분코드(유가, 코스닥) 전체), 기준은 로그인 사용자의 부서 소속을 기준으로 한다.
//alert('InfoMenuID():'+InfoMenuID());
/*
var fr_SecuGrpId = fn_getSecuGrpId(InfoMenuID()); // 증권그룹ID
//var fr_SearchTyp;
*/

/* 2단계까지 상위frame을 조회, 차후 변경 요망 */
//var fr_SecuGrpId = frame.Provider("../").fr_SecuGrpId;
//if (fr_SecuGrpId == undefined || fr_SecuGrpId == "") { fr_SecuGrpId = frame.Provider("../../").fr_SecuGrpId; }

scwin.TOP_FRAME = $c.frame.path("/");
scwin.s = undefined, scwin.f;
if (frame !== scwin.TOP_FRAME) {
    for (scwin.f = $c.frame.path("../"); scwin.s === undefined; scwin.f = $c.frame.path("../")) {
        scwin.s = scwin.f.scwin.fr_SecuGrpId;
        if (scwin.f === scwin.TOP_FRAME) break;
    }
}
scwin.fr_SecuGrpId = scwin.s;

///////// 2. 초기화 영역 /////////
scwin.onpageload = function() {
};

scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
scwin.txb_Search_onkeydown = function() {
    if (event.keyCode === 13) {
        scwin.listSync();
    }
};

scwin.dts_OnLoadError = function() {
    $c.win.alert(dts);
};

scwin.dts_OnLoadCompleted = function(rowcount) {
    if (dts.errorMsg) {
        alert(dts.errorMsg);
    } else {
        txb_TotCnt.setValue("총 " + rowcount + " 건");

        // 초기1회 초기값으로 설정된 회사코드를 검색한다.
        if (scwin.strCdSch !== "") {
            for (let i = 1; i <= dts.getRowCount(); i++) {
                if (scwin.strCdSch === dts.getCellData(i, 1)) {
                    dts.setRowPosition(i, 0);
                    break;
                }
            }
            scwin.strCdSch = "";
        }
    }
};

scwin.grd_OnDblClick = async function(row, colid) {
    let arrPar = new Array();

    //----W-Craft WebSquare 변환 확인: fn_SetPar----//
    if (scwin.fn_SetPar !== undefined) {
        arrPar[0] = {
            ISUR_CD: dts.getCellData(dts.getRowPosition(), "ISUR_CD"),
            COM_NM: dts.getCellData(dts.getRowPosition(), "COM_ABBRV"),
            SPOT_ISU_TRD_MKT_TP_CD: dts.getCellData(dts.getRowPosition(), "SPOT_ISU_TRD_MKT_TP_CD"),
            ACNTCLS_MM: dts.getCellData(dts.getRowPosition(), "ACNTCLS_MM"),
            SECUGRP_ID: dts.getCellData(dts.getRowPosition(), "SECUGRP_ID"), //fr_SecuGrpId값과 실제 발행기관의 증권그룹이 안맞는 경우가 있어서 증권그룹id를 넘김 	
            SECT_TP_CD: dts.getCellData(dts.getRowPosition(), "SECT_TP_CD"), //EMP_NM: dts.NameString(dts.RowPosition, "EMP_NM"),	
            DBCLICKYN: "Y"
        };

        //----W-Craft WebSquare 변환 확인: fn_SetPar----//
        scwin.fn_SetPar(arrPar);
    }
    await $c.win.closePopup();
};

scwin.img_Search_onclick = function() {
    scwin.listSync();
};

scwin.img_Close_onclick = async function() {
    await $c.win.closePopup();
};

///////// 5. 일반/업무 함수 영역 /////////
scwin.listSync = async function() {
    //var url = "/listingCommon.do?method=listCorpChrg&inputMessageId=CORP_CHRG_OUT&outputMessageId=CORP_CHRG_OUT" + "&COM_ABBRV=" + txb_Search.value +"&SECUGRP_ID=" + fr_SecuGrpId;
    const sbmOptions = {
        id : "sbm_dts",
        action : "/listingCommon.do",
        ref : "",
        target : "dts=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

scwin.gform_onload = function() {
    window.document.body.scroll = "no";
    let arrPar = new Array();
    /***************************************

	//----W-Craft WebSquare 변환 확인: fn_GetPar----//
    opener에  fn_GetPar의 이름을 가진 함수가 있다면, 이 펑션에 인수를 넘겨 값을 채워 이용한다. 없다면 업종조회후  최초 지정 코드값이 없는 상태

	//----W-Craft WebSquare 변환 확인: fn_SetPar----//
    opener에  fn_SetPar의 이름을 가진 함수가 있다면, 이 펑션에 인수를 넘겨 값을 채워 이용한다. 없다면 선택한 코드값과 코드명칭을 지정하지 않는다.
    ***************************************/
    const parentWin = $c.frame.path("../");

    //----W-Craft WebSquare 변환 확인: fn_GetPar----//
    scwin.fn_GetPar = parentWin.scwin.fn_GetPar;

    //----W-Craft WebSquare 변환 확인: fn_SetPar----//
    scwin.fn_SetPar = parentWin.scwin.fn_SetPar;
    //var fn_GetSearchTyp = parentWin.fn_GetSearchTyp;
    //fr_SearchTyp = fn_GetSearchTyp();
    //alert('[fr_SearchTyp]'+fr_SearchTyp);

    //----W-Craft WebSquare 변환 확인: fn_GetPar----//
    if (scwin.fn_GetPar !== undefined) {

        //----W-Craft WebSquare 변환 확인: fn_GetPar----//
        scwin.fn_GetPar(arrPar);
        strSch = ((arrPar.length >= 1) && (arrPar[0] !== undefined) ? arrPar[0] : "");
        if (scwin.fr_SecuGrpId === undefined) {
            scwin.fr_SecuGrpId = ((arrPar.length >= 3) && (arrPar[2] !== undefined) ? arrPar[2] : "");
        }
        if ((arrPar.length >= 4) && (arrPar[3] !== undefined)) {
            scwin.fr_MktId = arrPar[3];
        }
    }
    if (scwin.fr_MktId !== "9") {
        //전체
        $c.cm.setColumnProp(grd, "SPOT_ISU_TRD_MKT_TP_CD", "Show", false);
        $c.cm.setColumnProp(grd, "COM_ABBRV", "Width", $c.cm.getColumnProp(grd, "COM_ABBRV", "Width") + $c.cm.getColumnProp(grd, "SPOT_ISU_TRD_MKT_TP_CD", "Width"));
    }
    txb_Search.focus();
    scwin.listSync();
};
